def naive_research_guard(tokens_used: int, max_tokens: int, visited_hashes: set, url_hash: str) -> str:
    if tokens_used >= max_tokens:
        raise RuntimeError(f"Context budget exhausted: {tokens_used}/{max_tokens}")
    if url_hash in visited_hashes:
        return "SKIP_DUPLICATE"
    visited_hashes.add(url_hash)
    return "FETCH_ALLOWED"

async def run_research_dag_step(workflow_ctx, state: dict) -> dict:
    if state["hop_count"] >= 40:
        # Compact Temporal event history before hitting 50K event cap
        return await workflow_ctx.continue_as_new(state["compact_snapshot"])
    try:
        sub_results = await workflow_ctx.execute_activity(
            "dispatch_research_branch", state["pending_subgoals"],
            retry_policy={"maximum_attempts": 3, "backoff_coefficient": 2.0}
        )
        state["hop_count"] += len(sub_results)
        return state
    except Exception as exc:
        state["failed_branches"].append(str(exc))
        return state

def route_fetch_tier(content_type: str, js_challenge: bool, circuit_open: bool) -> str:
    if circuit_open:
        return "CIRCUIT_OPEN_SKIP"
    if not js_challenge and content_type in ("text/html-static", "application/pdf"):
        return "FAST_HTTP_CLIENT"
    return "FIRECRACKER_PLAYWRIGHT_VM"

def verify_claim_entailment(claim: str, span_texts: list[str], nli_scorer, tau: float = 0.82) -> bool:
    if not span_texts:
        return False
    best_score = max(nli_scorer(premise=s, hypothesis=claim) for s in span_texts)
    return best_score >= tau
